import {searchProjects} from './matcher.js';
export const track=(event,metadata={})=>{const safe={};for(const key of ['productType','resultCount','command','source'])if(metadata[key]!==undefined)safe[key]=metadata[key];if(Array.isArray(window.dataLayer))window.dataLayer.push({event,...safe});document.dispatchEvent(new CustomEvent('devmania:analytics',{detail:{event,...safe}}))};
export const el=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n};
export function modal(title){const d=el('dialog',undefined,'os-dialog');const top=el('div',undefined,'os-modal-head');const h=el('h2',title);h.id='modal-title-'+Math.random().toString(36).slice(2);d.setAttribute('aria-labelledby',h.id);const x=el('button','Close','os-close');x.type='button';x.onclick=()=>d.close();top.append(h,x);d.append(top);const content=el('div',undefined,'os-modal-content');d.append(content);const trigger=document.activeElement;d.addEventListener('close',()=>{d.remove();trigger?.focus()});document.body.append(d);d.showModal();return{dialog:d,content}}
let registry=[];let filterIds=null;let bootDone=false;
function boot(){let seen=true;try{seen=sessionStorage.getItem('devmaniaBootSeen')==='1';sessionStorage.setItem('devmaniaBootSeen','1')}catch{}if(seen||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const overlay=el('div',undefined,'os-boot');overlay.setAttribute('role','status');const label=el('strong','DEV//MANIA');const lines=el('pre','INITIALIZING...');const skip=el('button','Skip introduction','os-close');overlay.append(label,lines,skip);document.body.append(overlay);
 const steps=['Loading projects............. ✓','Loading mobile apps.......... ✓','Loading experiments.......... ✓','Loading questionable ideas... ✓','SYSTEM READY.\nWELCOME TO DEVMANIA.'];let i=0;
 const finish=(skipped=false)=>{if(bootDone)return;bootDone=true;clearInterval(t);clearTimeout(end);overlay.remove();document.removeEventListener('keydown',key);track(skipped?'devmania_boot_skipped':'devmania_boot_completed')};const key=()=>finish(true);document.addEventListener('keydown',key);overlay.onclick=()=>finish(true);const t=setInterval(()=>{if(i<steps.length)lines.textContent+='\n'+steps[i++]},330);const end=setTimeout(()=>finish(),2200);
}
boot();
export function focusProject(p){document.querySelector('.os-dialog')?.close();resetFilter();const card=document.getElementById('project-'+p.id);if(card){card.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});card.setAttribute('tabindex','-1');card.focus({preventScroll:true});card.classList.add('project-highlight');setTimeout(()=>card.classList.remove('project-highlight'),2200)}}
export function contact(brief='',type=''){document.querySelector('.os-dialog')?.close();const form=document.getElementById('brief-form');if(brief)form.elements.idea.value=brief;const select=form.elements.type;if(type){const option=[...select.options].find(o=>o.textContent.toLowerCase().includes(type.toLowerCase()));if(option)select.value=option.value}form.scrollIntoView({behavior:'smooth',block:'center'});form.elements.idea.focus({preventScroll:true});track('contact_started',{source:'interactive'})}
let filterBanner;
function resetFilter(){filterIds=null;document.querySelectorAll('.work-card').forEach(c=>{c.hidden=false;c.classList.remove('project-highlight')});document.querySelectorAll('.work-status-group,.work-category').forEach(c=>c.hidden=false);if(filterBanner)filterBanner.hidden=true}
function filterProjects(ps){filterIds=new Set(ps.map(p=>p.id));document.querySelectorAll('.work-card').forEach(c=>{c.hidden=!filterIds.has(c.dataset.projectId)});document.querySelectorAll('.work-status-group').forEach(c=>c.hidden=![...c.querySelectorAll('.work-card')].some(n=>!n.hidden));document.querySelectorAll('.work-category').forEach(c=>c.hidden=![...c.querySelectorAll('.work-card')].some(n=>!n.hidden));filterBanner.hidden=false;filterBanner.querySelector('span').textContent=`Showing ${ps.length} matching project${ps.length===1?'':'s'}.`;track('project_filter_applied',{resultCount:ps.length});document.getElementById('work').scrollIntoView({behavior:'smooth'})}
export async function openBuilder(initial=''){track('idea_builder_started');const shell=modal('Build my idea');shell.content.textContent='Opening idea builder…';try{const mod=await import('./builder.js');mod.mountBuilder(shell,{projects:registry,initial,contact,focusProject,track,el})}catch{shell.content.replaceChildren(el('p','The idea builder could not load. You can still send your idea directly.'));const b=el('button','Continue to enquiry','button');b.onclick=()=>contact(initial);shell.content.append(b)}}
async function openTerminal(){track('terminal_opened');const shell=modal('Developer terminal');shell.dialog.classList.add('terminal-dialog');shell.content.textContent='Opening terminal…';try{const mod=await import('./terminal.js');mod.mountTerminal(shell,{projects:registry,contact,focusProject,track,el})}catch{shell.content.textContent='Terminal unavailable. Close this panel to continue browsing.'}}
function palette(){if(document.querySelector('dialog[open]'))return;track('command_palette_opened');const {dialog,content}=modal('Ask DevMania');const form=el('form');const label=el('label','Find a project or describe what you want to build');const input=el('input');input.type='search';input.placeholder='Try “show me booking platforms”';input.maxLength=500;label.append(input);const submit=el('button','Search','button');form.append(label,submit);const suggestions=el('div',undefined,'os-chips');['Mobile apps','Logistics','AI projects','Booking platforms','Newest projects'].forEach(q=>{const b=el('button',q);b.type='button';b.onclick=()=>{input.value=q;render()};suggestions.append(b)});const response=el('div');response.setAttribute('aria-live','polite');content.append(form,suggestions,response);
 function render(){track('command_submitted');const q=input.value;const result=searchProjects(q,registry);response.replaceChildren(el('p',result.message));const list=el('div',undefined,'os-results');result.projects.forEach(p=>{const b=el('button',undefined,'os-result');b.type='button';b.append(el('strong',p.name),el('span',`${p.categories[0]} · ${p.status==='live'?'Published':'In the Build'} · ${p.capabilities.join(', ')}`));b.onclick=()=>{track('project_opened_from_command');focusProject(p)};list.append(b)});response.append(list);if(result.projects.length){const apply=el('button','Show matching projects','button');apply.onclick=()=>{dialog.close();filterProjects(result.projects)};response.append(apply)}else{const build=el('button','Build my idea','button');build.onclick=()=>{dialog.close();openBuilder(q)};response.append(build)}const clear=el('button','Clear / Reset','os-close');clear.onclick=()=>{resetFilter();input.value='';response.replaceChildren();input.focus()};response.append(clear)}
 form.onsubmit=e=>{e.preventDefault();render()};input.focus();
}
fetch('projects.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(projects=>{registry=projects;filterBanner=el('div',undefined,'os-filter-banner');filterBanner.hidden=true;const reset=el('button','Reset portfolio','os-close');reset.onclick=resetFilter;filterBanner.append(el('span'),reset);document.getElementById('work').prepend(filterBanner);
 const dock=el('button',undefined,'os-command-dock');dock.type='button';dock.setAttribute('aria-haspopup','dialog');dock.append(el('span','⌘'),el('span','Ask DevMania anything…'),el('kbd','Ctrl / ⌘ K'));dock.onclick=palette;document.body.append(dock);
 document.querySelectorAll('[data-open-builder]').forEach(b=>b.onclick=()=>openBuilder());document.querySelectorAll('[data-open-terminal]').forEach(b=>b.onclick=openTerminal);
 document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();palette()}});
}).catch(()=>{document.querySelectorAll('[data-open-builder]').forEach(b=>b.onclick=()=>contact());document.querySelectorAll('[data-open-terminal]').forEach(b=>b.hidden=true)});
const sequence=['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight','b','a'];let position=0,maniaTimer,maniaNote;
function stopMania(){clearTimeout(maniaTimer);document.body.classList.remove('mania-mode');maniaNote?.remove()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){stopMania();return}if(e.target.closest('input,textarea,select,[contenteditable]'))return;const key=e.key.length===1?e.key.toLowerCase():e.key;position=key===sequence[position]?position+1:key===sequence[0]?1:0;if(position===sequence.length){position=0;stopMania();document.body.classList.add('mania-mode');maniaNote=el('div','MANIA MODE ACTIVATED · Escape to exit','mania-note');maniaNote.setAttribute('role','status');document.body.append(maniaNote);track('mania_mode_activated');maniaTimer=setTimeout(stopMania,5500)}});
document.getElementById('brief-form').addEventListener('submit',()=>track('contact_started',{source:'form'}));
